}
</code></pre> <p>Hier handelt es sich um einen Code, der dem des in Abschnitt 11.6.1 behandelten Echo-Servers ähnelt. Wir gehen nur auf die Unterschiede ein:</p> <ul> <li>Zeile 7: Der Beratungsdienst wird gestartet   </li> <li>Zeile 9: Es wird vermerkt, dass der Dienst nun aktiv ist   </li> </ul> <p>Linie 21: Die Kunden werden von Service-Threads bedient, die die folgende Methode „doService“ ausführen:</p> <pre><code>
private static void doService(Object infos) {
            // Der zu bedienende Kunde wird abgerufen
            Client client = infos as Client;
            // erbringt die Dienstleistung für den Kunden
            Console.WriteLine("Début du service au client {0}", client.NumClient);
            // Auswertung der Verbindung TcpClient
            try {
                using (TcpClient tcpClient = client.CanalTcp) {
                    using (NetworkStream networkStream = tcpClient.GetStream()) {
                        using (StreamReader reader = new StreamReader(networkStream)) {
                            using (StreamWriter writer = new StreamWriter(networkStream)) {
                                // ungepufferter Ausgabestrom
                                writer.AutoFlush = true;
                                // Versenden einer Willkommensnachricht an den Kunden
                                writer.WriteLine("Bienvenue sur le serveur de calcul de l'impôt");
                                // Schleife für Leseanforderung/Schreibantwort
                                string demande = null;
                                bool serviceFini = false;
                                while (!serviceFini &amp;&amp; (demande = reader.ReadLine()) != null) {
                                    // Konsolenüberwachung
                                    if (echo) {
                                        Console.WriteLine("&lt;--- Client {0} : {1}", client.NumClient, demande);
                                    }
                                    // Anfrageauswertung
                                    demande = demande.Trim().ToLower();
                                    // Leere Anfrage?
                                    if (demande.Length == 0) {
                                        // Fehlerhafte Anfrage
                                        writeClient(writer,client.NumClient,"Commande non reconnue. Utilisez la commande aide.");
                                        return;
                                    }

                                    // Aufschlüsselung der Anfrage in Felder
                                    string[] champs = Regex.Split(demande, @"\s+");
                                    // Analyse
                                    switch (champs[0].ToLower()) {
                                        case "aide":
                                            writeClient(writer, client.NumClient, "Commandes acceptées\n1-aide\n2-impot marié(O/N) nbEnfants salaireAnnuel\n3-aurevoir");
                                            break;
                                        case "impot":
                                            // Steuerberechnung
                                            writeClient(writer, client.NumClient, calculImpot(writer, client.NumClient, champs));
                                            break;
                                        case "aurevoir":
                                            serviceFini = true;
                                            writeClient(writer, client.NumClient, "Au revoir...");
                                            break;
                                        default:
                                            writeClient(writer, client.NumClient, "Commande non reconnue. Utilisez la commande aide.");
                                            break;
                                    }
                                }
                            }
                        }
                    }
                }
            } catch (Exception e) {
                // Fehler
                Console.WriteLine("L'erreur suivante s'est produite lors du service au client {0} : {1}", client.NumClient, e.Message);
            } finally {
                Console.WriteLine("Fin du service au client {0}", client.NumClient);
            }
        }

        private static void writeClient(StreamWriter writer, int numClient, string message) {
            // Konsolenausgabe?
            if (echo) {
                Console.WriteLine("---&gt; Client {0} : {1}", numClient, message);
            }
            // Nachricht an den Kunden senden
            writer.WriteLine(message);
}
</code></pre> <p>Auch hier handelt es sich um einen Code, der dem des in Abschnitt 11.6.1 behandelten Echo-Servers ähnelt. Wir gehen nur auf die Unterschiede ein:</p> <ul> <li>Zeile 15: Sobald der Client verbunden ist, sendet der Server ihm eine Willkommensnachricht.   </li> <li>Zeilen 19–52: Die Schleife zum Einlesen der Befehle des Clients. Die Schleife endet, wenn der Client den Befehl „aurevoir“ sendet.   </li> <li>Zeile 27: Fall eines leeren Befehls   </li> <li>Zeile 34: Die Anfrage wird zur Analyse in Felder zerlegt   </li> <li>Zeile 37: Befehl aide: Der Client fordert die Liste der zulässigen Befehle an   </li> <li>Zeile 40: Befehl impot: Der Kunde fordert eine Steuerberechnung an. Die Antwort erfolgt mit der von der Methode calculImpot zurückgegebenen Meldung, auf die wir im Folgenden näher eingehen werden.   </li> <li>Zeile 44: Befehl aurevoir: Der Kunde gibt an, dass er fertig ist.   </li> <li>Zeile 45: Es werden Vorbereitungen getroffen, um die Schleife zum Lesen der Kundenanfragen (Zeilen 19–52) zu verlassen   </li> <li>Zeile 46: Wir antworten dem Kunden mit einer Abschiedsnachricht.   </li> <li>Zeile 48: Ein ungültiger Befehl. Dem Kunden wird eine Fehlermeldung gesendet.   </li> </ul> <p>Die Verarbeitung des Befehls impot erfolgt durch die folgende Methode calculImpot:</p> <pre><code>
private static string calculImpot(StreamWriter writer, int numClient, string[] champs) {
            // Abfrage zur Berechnung „verheiratet“ (J/N) nbEnfants salaireAnnuel
            // Es sind 4 Felder erforderlich
            if (champs.Length != 4) {
                return "Commande calcul incorrecte. Utilisez la commande aide.";
            }
            // Felder [1]
            string marié = champs[1];
            if (marié != "o" &amp;&amp; marié != "n") {
                return "Commande calcul incorrecte. Utilisez la commande aide.";
            }
            // Felder [2]
            int nbEnfants;
            if (!int.TryParse(champs[2], out nbEnfants)) {
                return "Commande calcul incorrecte. Utilisez la commande aide.";
            }
            // Felder [3]
            int salaireAnnuel;
            if (!int.TryParse(champs[3], out salaireAnnuel)) {
                return "Commande calcul incorrecte. Utilisez la commande aide.";
            }
            // Alles klar – die Steuer wird berechnet
            int impot = 0;
            try {
                impot = metier.CalculerImpot(marié == "o", nbEnfants, salaireAnnuel);
                return impot.ToString();
            } catch (Exception ex) {
                return ex.Message;
